# Load all grids from the session
import os, re

def load_all_grids():
    d = os.path.normpath(os.environ.get('RLM_SESSION_DIR', ''))
    if not d:
        return {}
    base = d + '/../../sessions/' + os.path.basename(d) + '.jsonl'
    try:
        content = open(base).read()
    except:
        return {}

    grids = {}
    # Pattern to match demo pairs
    pattern = r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n'
    matches = re.findall(pattern, content)

    # Now extract the grid rows
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', content):
        k, h, w = m[1], int(m[2]), int(m[3])
        # Get the next h lines
        idx = m.end()
        grid_text = content[idx:idx + h * (w + 1)]
        rows = []
        curr = 0
        while curr < h * (w + 1) and len(rows) < h:
            line = grid_text[curr]
            curr += 1
            if line == '\n' and curr >= h * (w + 1) - 1:
                break
            if line.strip().split() and all(x.isdigit() for x in line.strip().split()):
                row = [int(x) for x in line.strip().split()]
                if len(row) == w:
                    rows.append(row)

        if k not in grids and rows:
            grids[k] = rows

    return grids

grids = load_all_grids()
print("Loaded grids:", sorted(grids.keys()))
for k, v in grids.items():
    print(f"\n{h}x{w} {k}:")
    print(v)

